-- APEX GYM - DỮ LIỆU MẪU LỚN, GIẢ LẬP PHÒNG GYM HOẠT ĐỘNG THẬT
-- Chạy SAU gym_db_full_api.sql. Chỉ làm sạch dữ liệu có username seed_*.
-- Tất cả tài khoản seed_* dùng mật khẩu 123456.
-- Nên tắt backend khi import để không phát realtime lịch sử hàng loạt.
-- ============================================================================
USE `gym_db`;
SET NAMES utf8mb4;
SET @seed_started_at = NOW();
SET @pwd_123456 = '$2b$12$3Uzqxyn/fWnKUmo1RzR.meToBLRCLxZErBZRvSNA3VDyut5jNZzRy';
SET @role_receptionist=(SELECT id FROM roles WHERE LOWER(name)='receptionist' LIMIT 1);
SET @role_member=(SELECT id FROM roles WHERE LOWER(name)='member' LIMIT 1);
SET @role_trainer=(SELECT id FROM roles WHERE LOWER(name)='trainer' LIMIT 1);
SET @admin_id=(SELECT id FROM users WHERE username='admin' LIMIT 1);
SET @creator_id=COALESCE((SELECT id FROM users WHERE username='receptionist' LIMIT 1),@admin_id);

-- 1. Dọn riêng dữ liệu seed cũ để có thể chạy lại file
DROP TEMPORARY TABLE IF EXISTS tmp_seed_users;
CREATE TEMPORARY TABLE tmp_seed_users AS SELECT id FROM users WHERE username LIKE 'seed\_%';
DROP TEMPORARY TABLE IF EXISTS tmp_seed_members;
CREATE TEMPORARY TABLE tmp_seed_members AS SELECT m.id FROM members m JOIN tmp_seed_users x ON x.id=m.user_id;
DROP TEMPORARY TABLE IF EXISTS tmp_seed_trainers;
CREATE TEMPORARY TABLE tmp_seed_trainers AS SELECT t.id FROM trainers t JOIN tmp_seed_users x ON x.id=t.user_id;
DROP TEMPORARY TABLE IF EXISTS tmp_seed_receptionists;
CREATE TEMPORARY TABLE tmp_seed_receptionists AS SELECT r.id FROM receptionists r JOIN tmp_seed_users x ON x.id=r.user_id;
SET FOREIGN_KEY_CHECKS=0;
DELETE FROM outbox_events WHERE target_user_id IN (SELECT id FROM tmp_seed_users);
DELETE FROM notifications WHERE user_id IN (SELECT id FROM tmp_seed_users);
DELETE FROM device_tokens WHERE user_id IN (SELECT id FROM tmp_seed_users);
DELETE FROM refresh_tokens WHERE user_id IN (SELECT id FROM tmp_seed_users);
DELETE FROM password_reset_otps WHERE user_id IN (SELECT id FROM tmp_seed_users);
DELETE FROM payroll_items WHERE employee_user_id IN (SELECT id FROM tmp_seed_users);
DELETE FROM membership_requests WHERE member_id IN (SELECT id FROM tmp_seed_members);
DELETE FROM payments WHERE member_id IN (SELECT id FROM tmp_seed_members);
DELETE FROM pt_sessions WHERE member_id IN (SELECT id FROM tmp_seed_members) OR trainer_id IN (SELECT id FROM tmp_seed_trainers);
DELETE FROM checkins WHERE member_id IN (SELECT id FROM tmp_seed_members) OR trainer_id IN (SELECT id FROM tmp_seed_trainers);
DELETE FROM qr_tokens WHERE user_id IN (SELECT id FROM tmp_seed_users);
DELETE FROM qr_demo WHERE (entity_type='member' AND entity_id IN (SELECT id FROM tmp_seed_members)) OR (entity_type='trainer' AND entity_id IN (SELECT id FROM tmp_seed_trainers));
DELETE FROM training_schedules WHERE member_id IN (SELECT id FROM tmp_seed_members) OR trainer_id IN (SELECT id FROM tmp_seed_trainers);
DELETE FROM trainer_availability WHERE trainer_id IN (SELECT id FROM tmp_seed_trainers);
DELETE FROM member_packages WHERE member_id IN (SELECT id FROM tmp_seed_members) OR pt_id IN (SELECT id FROM tmp_seed_trainers);
DELETE FROM members WHERE id IN (SELECT id FROM tmp_seed_members);
DELETE FROM trainers WHERE id IN (SELECT id FROM tmp_seed_trainers);
DELETE FROM receptionists WHERE id IN (SELECT id FROM tmp_seed_receptionists);
DELETE FROM transactions WHERE description LIKE '[SEED LARGE]%';
DELETE FROM expenses WHERE description LIKE '[SEED LARGE]%';
DELETE FROM users WHERE id IN (SELECT id FROM tmp_seed_users);
SET FOREIGN_KEY_CHECKS=1;

-- 2. Nhân sự: 4 lễ tân, 8 PT

-- 3. 80 hội viên

-- 4. Gói tập hiện tại và lịch sử hết hạn

-- 5. Khung giờ làm việc PT 14 ngày tới

-- 6. 300 lịch tập/lịch dạy

-- 7. 1000+ lượt check-in trong 50 ngày

-- 8. 220 buổi PT đã xác nhận/vắng/hủy

-- 9. Thanh toán, giao dịch và chi phí

-- 10. 40 yêu cầu gói tập

-- 11. Hơn 450 thông báo cho Flutter

-- 12. 40 thiết bị mobile giả lập

-- Không phát lại event lịch sử sau khi backend bật
DELETE FROM outbox_events WHERE target_user_id IN (SELECT id FROM users WHERE username LIKE 'seed\_%') AND created_at >= @seed_started_at;

-- Kết quả tổng hợp
SELECT 'Tài khoản seed' AS hang_muc,COUNT(*) AS so_luong FROM users WHERE username LIKE 'seed\_%'
UNION ALL SELECT 'PT seed',COUNT(*) FROM trainers t JOIN users u ON u.id=t.user_id WHERE u.username LIKE 'seed\_pt%'
UNION ALL SELECT 'Hội viên seed',COUNT(*) FROM members m JOIN users u ON u.id=m.user_id WHERE u.username LIKE 'seed\_hv%'
UNION ALL SELECT 'Gói đăng ký seed',COUNT(*) FROM member_packages mp JOIN members m ON m.id=mp.member_id JOIN users u ON u.id=m.user_id WHERE u.username LIKE 'seed\_hv%'
UNION ALL SELECT 'Lịch tập seed',COUNT(*) FROM training_schedules ts JOIN members m ON m.id=ts.member_id JOIN users u ON u.id=m.user_id WHERE u.username LIKE 'seed\_hv%'
UNION ALL SELECT 'Check-in seed',COUNT(*) FROM checkins c LEFT JOIN members m ON m.id=c.member_id LEFT JOIN trainers t ON t.id=c.trainer_id LEFT JOIN users um ON um.id=m.user_id LEFT JOIN users ut ON ut.id=t.user_id WHERE um.username LIKE 'seed\_%' OR ut.username LIKE 'seed\_%'
UNION ALL SELECT 'Buổi PT seed',COUNT(*) FROM pt_sessions ps JOIN members m ON m.id=ps.member_id JOIN users u ON u.id=m.user_id WHERE u.username LIKE 'seed\_hv%'
UNION ALL SELECT 'Thông báo seed',COUNT(*) FROM notifications n JOIN users u ON u.id=n.user_id WHERE u.username LIKE 'seed\_%';

